el('objectForm').onsubmit=async e=>{e.preventDefault();if(saving||!selected)return;saving=true;el('saveObject').disabled=true;el('saveStatus').textContent='Lagrer …';try{const p=formProduct();if(!!p.variantGroup!==!!p.variantLabel)throw Error('Fyll inn både gruppenavn og farge, eller velg «Ingen gruppe».');let next=products.some(x=>x.id===p.id)?products.map(x=>x.id===p.id?p:x):[...products,p];if(['product','module'].includes(kind(p)))next=linkVariantProducts(p,next,[...variantLinks].map(([id,label])=>({id,label})),products.find(x=>x.id===p.id)||null);if(p.moduleSeries)next=next.map(item=>item.moduleSeries===p.moduleSeries?{...item,rentalModuleMinimum:p.rentalModuleMinimum}:item);if(p.variantGroup)next=next.map(item=>item.variantGroup===p.variantGroup?{...item,variantDisplay:p.variantDisplay}:item);if(p.isPackage)next=next.map(item=>p.components.some(c=>c.id===item.id)&&Object.hasOwn(componentPriceDrafts,item.id)?{...item,purchaseUnitPrice:componentPriceDrafts[item.id]}:item);if(isWall(p))next=next.map(x=>x.wallGroup===p.wallGroup?{...x,wallCover:p.wallCover}:x);const data=await api('/api/admin/catalog',{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify({revision,products:next})});products=data.products;revision=data.revision;tab=isWall(p)?'walls':p.isPackage&&!isBedSet(p)&&!isTablewareRental(p,products)?'packages':'products';syncArea();edit(products.find(x=>x.id===p.id));el('saveStatus').textContent='Lagret. Endringen gjelder nå på nettsiden.';el('saveStatus').className='success';el('status').textContent='Lagret '+new Date(data.updatedAt).toLocaleString('nb');media=[];}catch(e){el('saveStatus').textContent=e.message;el('saveStatus').className='error';}finally{saving=false;el('saveObject').disabled=false;}};
document.addEventListener('click',e=>{const pickButton=e.target.closest('[data-pick]');if(pickButton){pick(pickButton.dataset.pick);return;}if(e.target.closest('[data-close-media]')){el('mediaDialog').close();return;}const use=e.target.closest('[data-use-image]');if(use){const url=use.dataset.useImage;if(mediaTarget==='gallery'){selected.gallery??=[];if(selected.gallery.length>=12){el('pickerStatus').textContent='Et produkt kan ha opptil 12 galleribilder.';return;}if(!selected.gallery.includes(url)&&selected.image!==url)selected.gallery.push(url);}else {selected[mediaTarget]=url;if(mediaTarget==='image')selected.gallery=(selected.gallery||[]).filter(src=>src!==url);}renderImages();setDirty();el('mediaDialog').close();return;}if(e.target.closest('[data-remove-main]')){selected.image='';renderImages();setDirty();}const rm=e.target.closest('[data-gallery-remove]');if(rm){selected.gallery.splice(Number(rm.dataset.galleryRemove),1);renderImages();setDirty();}const main=e.target.closest('[data-gallery-main]');if(main){const i=Number(main.dataset.galleryMain),old=selected.image;selected.image=selected.gallery[i];if(old)selected.gallery[i]=old;else selected.gallery.splice(i,1);renderImages();setDirty();}const move=e.target.closest('[data-gallery-move]');if(move){const i=Number(move.dataset.galleryMove);if(i>0)[selected.gallery[i-1],selected.gallery[i]]=[selected.gallery[i],selected.gallery[i-1]];renderImages();setDirty();}const frame=e.target.closest('[data-remove-frame]');if(frame){selected.wallFrames.splice(Number(frame.dataset.removeFrame),1);renderFrames();setDirty();}});
