const relationKinds={addons:'relatedAddOns',packages:'relatedPackages'};
function renderRelations(renderChoices=true){
 el('addonFor').textContent='Utleietilvalg til «'+(el('objectName').value.trim()||'nytt produkt')+'»';
 for(const [kind,property] of Object.entries(relationKinds)){
  const ids=selected[property]||[],chosen=ids.map(id=>products.find(p=>p.id===id)).filter(Boolean),query=el(kind+'Search').value.toLocaleLowerCase('nb');
  el(kind+'SelectedTitle').textContent=(kind==='addons'?'Valgte tilvalg':'Valgte ferdigpakker')+' ('+chosen.length+')';
  el(kind+'Selected').innerHTML=chosen.length?'<ul>'+chosen.map(p=>`<li><span>${escape(p.name)}${!p.active?' <small>Skjult på nettsiden – tilbys ikke kunden</small>':''}</span><button type="button" class="text-button" data-remove-relation="${kind}" data-relation-id="${p.id}" aria-label="Fjern ${escape(p.name)} som ${kind==='addons'?'tilvalg':'anbefalt pakke'}">Fjern</button></li>`).join('')+'</ul>':'<p class="hint">'+(kind==='addons'?'Ingen tilvalg valgt. Kunden velger bare hovedproduktet.':'Ingen ferdigpakker valgt.')+'</p>';
  if(renderChoices){const candidates=products.filter(p=>!p.deletedAt&&p.id!==selected.id&&(kind==='packages'?p.isPackage:!p.isPackage)&&(p.name+' '+p.category).toLocaleLowerCase('nb').includes(query)).sort((a,b)=>Number(ids.includes(b.id))-Number(ids.includes(a.id))||Number(b.active)-Number(a.active)||a.name.localeCompare(b.name,'nb'));el(kind+'Choices').innerHTML=candidates.map(p=>`<label class="relation-choice ${ids.includes(p.id)?'is-selected':''}"><input type="checkbox" data-relation="${kind}" value="${p.id}" ${ids.includes(p.id)?'checked':''}><span><strong>${escape(p.name)}</strong><small>${escape(categoryLabel(p.category))}${!p.active?' · Skjult på nettsiden':''}${kind==='addons'?' · '+(p.priceOnRequest?'Pris på forespørsel':resolvedRentalRates(p,products).price.toLocaleString('nb')+(p.rentalPricingMode==='period'?' kr/leieperiode':' kr/døgn')):''}</small></span></label>`).join('')||'<p class="hint">Ingen treff. Prøv et annet søkeord.</p>';
  }else for(const input of el(kind+'Choices').querySelectorAll('input')){input.checked=ids.includes(input.value);input.closest('label').classList.toggle('is-selected',input.checked);}
 }
 el('proposalDefaults').innerHTML=(selected.relatedAddOns||[]).map(id=>products.find(p=>p.id===id)).filter(Boolean).map(p=>`<label class="check-label"><input type="checkbox" data-proposal-default="${p.id}" ${(selected.suggestedAddOns||[]).includes(p.id)?'checked':''}><span>${escape(p.name)}</span></label>`).join('')||'<p class="hint">Velg tilvalg nedenfor først, og kryss så av de som skal være foreslått.</p>';
 el('packagesSummary').textContent='Anbefalte ferdigpakker ('+(selected.relatedPackages||[]).length+')';
}
for(const kind of Object.keys(relationKinds))el(kind+'Search').oninput=()=>renderRelations();
el('objectName').addEventListener('input',()=>renderRelations(false));
document.addEventListener('change',event=>{const input=event.target.closest('[data-relation]');if(!input)return;const key=relationKinds[input.dataset.relation],ids=new Set(selected[key]||[]);if(input.checked)ids.add(input.value);else ids.delete(input.value);selected[key]=[...ids];renderRelations(false);setDirty();});
document.addEventListener('click',event=>{const button=event.target.closest('[data-remove-relation]');if(!button)return;const kind=button.dataset.removeRelation,key=relationKinds[kind];selected[key]=(selected[key]||[]).filter(id=>id!==button.dataset.relationId);renderRelations();setDirty();el(kind+'Search').focus();});

function dependencies(id){return products.filter(p=>!p.deletedAt&&p.id!==id).flatMap(p=>{const uses=[];if(p.requiredProductId===id)uses.push('kreves av tilvalget');if(p.components?.some(c=>c.id===id))uses.push('fast innhold i pakken');if(p.relatedAddOns?.includes(id))uses.push('valgfritt tilvalg');if(p.rentalAlternatives?.includes(id))uses.push('alternativ ved leie');if(p.recommendedProducts?.includes(id))uses.push('anbefalt produkt');if(p.relatedPackages?.includes(id))uses.push('anbefalt pakke');return uses.length?[{name:p.name,uses:uses.join(', ')}]:[];});}
function renderTrash(){el('emptyTrash').disabled=trashLoading||!products.some(p=>p.deletedAt)&&!media.some(m=>m.deletedAt);const deleted=products.filter(p=>p.deletedAt);el('trashList').innerHTML=deleted.length?deleted.map(p=>`<article class="trash-item"><div><h3>${escape(p.name)}</h3><p>${escape(categoryLabel(p.category))} · Slettet ${new Date(p.deletedAt).toLocaleDateString('nb')}</p></div><button type="button" class="button button-outline" data-restore-product="${p.id}">Gjenopprett</button><button type="button" class="button danger-button" data-purge-product="${p.id}">Slett permanent</button></article>`).join(''):'<p class="hint">Ingen produkter i papirkurven.</p>';const images=media.filter(m=>m.deletedAt);el('imageTrashList').innerHTML=images.length?images.map(m=>`<article class="trash-item"><button type="button" class="image-zoom" data-zoom="${escape(m.url)}" aria-label="Se ${escape(m.name)} større"><img class="trash-image" src="${escape(m.url)}" alt="${escape(m.name)}"></button><div><h3>${escape(m.name)}</h3><p>Flyttet til papirkurven ${new Date(m.deletedAt).toLocaleDateString('nb')}</p></div><button type="button" class="button button-outline" data-restore-image="${escape(m.url)}">Gjenopprett bilde</button><button type="button" class="button danger-button" data-purge-image="${escape(m.url)}">Slett permanent</button></article>`).join(''):'<p class="hint">Ingen bilder i papirkurven.</p>';}

async function lifecycle(id,action){const data=await api('/api/admin/products/'+id+'/'+action,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({revision})});products=data.products;revision=data.revision;setDirty(false);media=[];list();renderTrash();el('status').textContent='Katalogen er lagret i databasen · '+products.filter(p=>!p.deletedAt).length+' oppføringer';return data;}
el('deleteObject').onclick=()=>{const product=products.find(p=>p.id===selected?.id);if(!product)return;const uses=dependencies(product.id);el('deleteTitle').textContent='Slett «'+product.name+'»?';el('deleteDescription').textContent='Produktet flyttes til papirkurven og fjernes fra nettsiden. Bilder beholdes, og produktet kan gjenopprettes.'+(dirty?' Ulagrede endringer blir ikke lagret.':'');el('deleteDependencies').innerHTML=uses.length?'<p>Fjern disse koblingene før du sletter produktet:</p><ul>'+uses.map(p=>'<li><strong>'+escape(p.name)+'</strong> · '+escape(p.uses)+'</li>').join('')+'</ul>':'';el('confirmDelete').disabled=uses.length>0;el('deleteStatus').textContent='';el('deleteDialog').showModal();};
el('cancelDelete').onclick=()=>el('deleteDialog').close();
el('confirmDelete').onclick=async()=>{const id=selected.id;el('confirmDelete').disabled=true;try{await lifecycle(id,'trash');el('adminSearch').value='';el('deleteDialog').close();selectVisible();el('status').textContent='Produktet er flyttet til papirkurven og kan gjenopprettes.';}catch(error){el('deleteStatus').textContent=error.message;}finally{el('confirmDelete').disabled=false;}};
document.addEventListener('click',async event=>{const button=event.target.closest('[data-restore-product]');if(!button)return;button.disabled=true;try{await lifecycle(button.dataset.restoreProduct,'restore');el('trashStatus').textContent='Produktet er gjenopprettet. Det ligger under Produkter eller Bildevegger og er skjult til du velger «Vis på nettsiden».';}catch(error){el('trashStatus').textContent=error.message;}finally{button.disabled=false;}});

let deletingImage='';
function openMediaProduct(id){const product=products.find(p=>p.id===id&&!p.deletedAt);if(!product)return;if(dirty&&!confirm('Forkaste ulagrede endringer og åpne produktet?'))return;setDirty(false);el('imageDeleteDialog').close();el('mediaDialog').close();switchTab(isWall(product)?'walls':product.isPackage&&!isBedSet(product)?'packages':'products');edit(product);el('objectName').focus();}
el('cancelImageDelete').onclick=()=>el('imageDeleteDialog').close();
el('confirmImageDelete').onclick=async()=>{el('confirmImageDelete').disabled=true;try{await api('/api/admin/media/trash',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({url:deletingImage})});await loadMedia();renderTrash();el('imageDeleteDialog').close();el('libraryStatus').textContent='Bildet er flyttet til papirkurven og kan gjenopprettes.';}catch(error){el('imageDeleteStatus').textContent=error.message;}finally{el('confirmImageDelete').disabled=false;}};
document.addEventListener('click',async event=>{const linked=event.target.closest('[data-media-product]');if(linked){openMediaProduct(linked.dataset.mediaProduct);return;}const button=event.target.closest('[data-trash-image]');if(button){const image=media.find(m=>m.url===button.dataset.trashImage);if(!image)return;deletingImage=image.url;el('imageDeleteName').textContent=image.name;el('imageDeletePreview').src=image.url;el('imageDeleteStatus').textContent='';el('imageDeleteUses').innerHTML=image.usedBy.length?'<p>Fjern bildet fra disse produktene før sletting:</p><ul>'+image.usedBy.map(p=>`<li>${p.deletedAt?escape(p.name)+' (i papirkurven)':`<button type="button" class="media-product-link" data-media-product="${p.id}">${escape(p.name)}</button>`}</li>`).join('')+'</ul>':'';el('confirmImageDelete').disabled=image.usedBy.length>0;el('imageDeleteDialog').showModal();return;}const restore=event.target.closest('[data-restore-image]');if(restore){restore.disabled=true;try{await api('/api/admin/media/restore',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({url:restore.dataset.restoreImage})});await loadMedia();renderTrash();el('trashStatus').textContent='Bildet er gjenopprettet i bildebiblioteket.';}catch(error){el('trashStatus').textContent=error.message;}finally{restore.disabled=false;}}});

el('adminCategories').addEventListener('click',event=>{const button=event.target.closest('[data-admin-category]');if(!button||button.dataset.adminCategory===categoryFilter)return;if(dirty&&!confirm('Forkaste ulagrede endringer og bytte kategori?'))return;setDirty(false);categoryFilter=button.dataset.adminCategory;rememberCategory();selectVisible();[...el('adminCategories').querySelectorAll('button')].find(b=>b.dataset.adminCategory===categoryFilter)?.focus();});

let purgeSelection=null;
function openPurge(productIds,mediaUrls,all=false){
 const items=products.filter(p=>productIds.includes(p.id)),images=media.filter(m=>mediaUrls.includes(m.url));
 purgeSelection={productIds,mediaUrls,revision};
 el('purgeTitle').textContent=all?'Tøm papirkurven?':'Slett permanent?';
 el('purgeDescription').textContent='Dette fjerner '+[items.length?items.length+' '+(items.length===1?'produkt':'produkter'):'',images.length?images.length+' '+(images.length===1?'bilde':'bilder'):''].filter(Boolean).join(' og ')+' permanent. Dette kan ikke angres.';
 el('purgeItems').innerHTML=[...items.map(p=>p.name+' (produkt)'),...images.map(m=>m.name+' (bilde)')].map(name=>'<li>'+escape(name)+'</li>').join('');
 el('purgeWarning').textContent=items.length?'Bildene til produktene beholdes i bildebiblioteket, bortsett fra bilder som også er valgt for sletting her. Koblinger til andre produkter kontrolleres før sletting.':'Bilder som brukes av et produkt, også et produkt i papirkurven, kan ikke slettes.';
 el('purgeConfirmation').value='';el('confirmPurge').disabled=true;el('purgeStatus').textContent='';el('purgeDialog').showModal();el('purgeConfirmation').focus();
}
el('emptyTrash').onclick=()=>openPurge(products.filter(p=>p.deletedAt).map(p=>p.id),media.filter(m=>m.deletedAt).map(m=>m.url),true);
document.addEventListener('click',event=>{const p=event.target.closest('[data-purge-product]'),m=event.target.closest('[data-purge-image]');if(p)openPurge([p.dataset.purgeProduct],[]);if(m)openPurge([],[m.dataset.purgeImage]);});
el('cancelPurge').onclick=()=>el('purgeDialog').close();
el('purgeConfirmation').oninput=()=>{el('confirmPurge').disabled=el('purgeConfirmation').value!=='SLETT';};
el('confirmPurge').onclick=async()=>{
 if(!purgeSelection||el('purgeConfirmation').value!=='SLETT')return;
 el('confirmPurge').disabled=true;el('cancelPurge').disabled=true;
 try{const data=await api('/api/admin/trash/purge',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({...purgeSelection,confirmation:el('purgeConfirmation').value})});products=data.products;revision=data.revision;setDirty(false);list();await loadMedia();renderTrash();el('purgeDialog').close();el('trashStatus').textContent='Det valgte innholdet er slettet permanent. Bilder til slettede produkter beholdes i bildebiblioteket hvis de ikke også var valgt.';el('status').textContent='Katalogen er lagret i databasen · '+products.filter(p=>!p.deletedAt).length+' oppføringer';purgeSelection=null;el('emptyTrash').focus();}
 catch(error){el('purgeStatus').textContent=error.message;}
 finally{el('cancelPurge').disabled=false;el('confirmPurge').disabled=el('purgeConfirmation').value!=='SLETT';}
};

document.addEventListener('change',event=>{const input=event.target.closest('[data-proposal-default]');if(!input)return;const ids=new Set(selected.suggestedAddOns||[]);if(input.checked)ids.add(input.dataset.proposalDefault);else ids.delete(input.dataset.proposalDefault);selected.suggestedAddOns=[...ids];setDirty();});

function currentPackagePurchaseBreakdown(){const components=[...document.querySelectorAll('[data-component]:checked')].map(c=>({id:c.dataset.component,quantity:Number(document.querySelector(`[data-count="${c.dataset.component}"]`).value)}));return packagePurchaseBreakdown({components},products.map(p=>Object.hasOwn(componentPriceDrafts,p.id)?{...p,purchaseUnitPrice:componentPriceDrafts[p.id]}:p));}
const purchaseMoney=value=>new Intl.NumberFormat('nb-NO',{style:'currency',currency:'NOK',maximumFractionDigits:2}).format(value);
function updatePackagePurchaseSummary(){const target=el('packagePurchaseTotal');if(!target)return;const result=currentPackagePurchaseBreakdown();target.textContent='Beregnet kjøpspris: '+(result.total===null?'Pris på forespørsel':purchaseMoney(result.total));el('packagePurchaseMissing').textContent=result.missing.length?'Mangler kjøpspris: '+result.missing.map(line=>line.name).join(', '):'Kjøpspris for hele pakkens faste innhold inkl. mva.';}
function renderPackagePurchasePreview(){const target=el('packagePurchasePreview');if(!selected||el('productKind').value!=='package'||!el('objectBusinessPurchase').checked||el('objectPurchasePriceMode').value!=='components'){target.innerHTML='';return;}const result=currentPackagePurchaseBreakdown();target.innerHTML='<p><strong id="packagePurchaseTotal"></strong></p><p class="hint">Veiledende salgspris per stk. inkl. mva. Prisene lagres på produktene og brukes også i andre pakker med samme produkt.</p>'+result.lines.map(line=>'<label>'+escape(line.quantity)+' × '+escape(line.name)+'<input type="number" min="0.01" max="100000000" step="0.01" data-component-purchase-price="'+escape(line.id)+'" value="'+(line.unitPrice??'')+'" placeholder="Veiledende salgspris – ikke oppgitt"></label>').join('')+'<p class="hint" id="packagePurchaseMissing"></p>';updatePackagePurchaseSummary();}
el('objectForm').addEventListener('input',event=>{if(!event.target.matches('[data-component-purchase-price]'))return;componentPriceDrafts[event.target.dataset.componentPurchasePrice]=event.target.value===''?null:Number(event.target.value);updatePackagePurchaseSummary();syncRentalPricing();});
el('objectForm').addEventListener('input',event=>{if(event.target.matches('[data-component],[data-count]'))renderPackagePurchasePreview();});
el('objectForm').addEventListener('change',event=>{if(event.target.matches('[data-component]'))renderPackagePurchasePreview();});

function variantEligible(p){return !p.deletedAt&&compatibleVariants({...selected,category:el('objectCategory').value,moduleSeries:el('productKind').value==='module'?el('objectModuleSeries').value:'',moduleRole:el('objectModuleRole').value},p);}
function guessedColour(p){return variantFields(p).variantLabel||p.name.split(',').at(-1).trim();}
function initVariantLinks(p){variantLinks=new Map();const group=variantFields(p).variantGroup;if(group)for(const peer of products)if(peer.id!==p.id&&variantEligible(peer)&&peer.category===p.category&&variantFields(peer).variantGroup===group)variantLinks.set(peer.id,guessedColour(peer));el('variantSearch').value='';renderVariantLinks();}
function renderVariantLinks(){
 const category=el('objectCategory').value,q=el('variantSearch').value.toLocaleLowerCase('nb');
 const row=p=>`<div class="variant-link-row"><label class="check-label"><input type="checkbox" data-variant-link="${p.id}" ${variantLinks.has(p.id)?'checked':''}><span>${p.image?`<img src="${escape(p.image)}" alt="">`:''}<strong>${escape(p.name)}</strong><small>${p.rentalEnabled===false?'Kun kjøp':p.stock+' stk. til leie'}${p.saleEnabled?' · kan kjøpes':''}${!p.active?' · skjult':''}</small></span></label>${variantLinks.has(p.id)?`<label>Farge / variantnavn<input maxlength="80" data-variant-colour="${p.id}" value="${escape(variantLinks.get(p.id))}" aria-label="Farge for ${escape(p.name)}" required></label>`:''}</div>`;
 const peers=products.filter(p=>p.id!==selected.id&&variantEligible(p)&&p.category===category);
 el('variantSelected').innerHTML=peers.filter(p=>variantLinks.has(p.id)).map(row).join('')||'<p class="hint">Ingen andre farger koblet til ennå.</p>';
 el('variantChoices').innerHTML=peers.filter(p=>!variantLinks.has(p.id)&&p.name.toLocaleLowerCase('nb').includes(q)).sort((a,b)=>a.name.localeCompare(b.name,'nb')).map(row).join('')||'<p class="hint">Ingen flere treff i samme kategori.</p>';
 const group=el('objectVariantGroup').value,groups=[...new Set(products.filter(p=>variantEligible(p)&&p.category===category).map(p=>variantFields(p).variantGroup).filter(Boolean))];if(group&&!groups.includes(group))groups.push(group);
 el('variantGroupSelect').innerHTML='<option value="">Ingen gruppe</option><option value="__new__">Opprett ny gruppe</option>'+groups.sort((a,b)=>a.localeCompare(b,'nb')).map(g=>`<option value="${escape(g)}">${escape(g)}</option>`).join('');el('variantGroupSelect').value=group||'';
 const members=[selected,...peers.filter(p=>variantLinks.has(p.id))];el('variantGroupPreview').textContent=group?group+' · '+members.length+' farge'+(members.length===1?'':'r')+' · '+members.filter(p=>p.rentalEnabled!==false&&p.stock>0).length+' til leie · '+members.filter(salesEnabled).length+' til kjøp':'Ingen gruppe valgt. Velg en gruppe eller finn en annen farge nedenfor.';el('leaveVariantGroup').hidden=!group;
 el('objectVariantLabel').required=variantLinks.size>0||!!group;
}
el('variantSearch').oninput=renderVariantLinks;
el('objectSubcategory').addEventListener('change',()=>{syncSubcategory();setDirty();});
el('objectCategory').addEventListener('change',()=>{syncSubcategory('');syncKind();variantLinks.clear();el('objectVariantGroup').value='';el('objectVariantLabel').value='';renderVariantLinks();});
document.addEventListener('change',event=>{const input=event.target.closest('[data-variant-link]');if(!input)return;const peer=products.find(p=>p.id===input.dataset.variantLink);if(input.checked){const group=variantFields(peer).variantGroup;if(!el('objectVariantGroup').value)el('objectVariantGroup').value=group||(el('objectName').value.split(',').slice(0,-1).join(',').trim()||el('objectName').value.trim()||'Fargevarianter');for(const p of products.filter(p=>p.id!==selected.id&&variantEligible(p)&&p.category===peer.category&&(p.id===peer.id||group&&variantFields(p).variantGroup===group)))variantLinks.set(p.id,guessedColour(p));if(!el('objectVariantLabel').value)el('objectVariantLabel').value=el('objectName').value.split(',').at(-1).trim();}else variantLinks.delete(peer.id);renderVariantLinks();setDirty();});
document.addEventListener('input',event=>{const input=event.target.closest('[data-variant-colour]');if(input){variantLinks.set(input.dataset.variantColour,input.value);setDirty();}});

el('variantGroupSelect').onchange=()=>{const group=el('variantGroupSelect').value;variantLinks.clear();el('objectVariantGroup').value=group==='__new__'?'':group;if(group==='__new__'){el('objectVariantGroup').focus();el('variantGroupPreview').textContent='Skriv et gruppenavn og fargen på produktet. Legg deretter til de andre fargene.';setDirty();return;}if(group)for(const peer of products.filter(p=>p.id!==selected.id&&variantEligible(p)&&p.category===el('objectCategory').value&&variantFields(p).variantGroup===group))variantLinks.set(peer.id,guessedColour(peer));if(group&&!el('objectVariantLabel').value)el('objectVariantLabel').value=guessedColour(selected);if(!group)el('objectVariantLabel').value='';renderVariantLinks();setDirty();};
el('objectVariantGroup').addEventListener('input',()=>{renderVariantLinks();setDirty();});
el('leaveVariantGroup').onclick=()=>{variantLinks.clear();el('objectVariantGroup').value='';el('objectVariantLabel').value='';renderVariantLinks();setDirty();};

let importDraft=null;
el('catalogImport').onchange=async e=>{importDraft=null;el('saveImport').hidden=true;try{const file=e.target.files[0];if(!file)return;if(file.size>2000000)throw Error('Filen er for stor.');const data=JSON.parse(await file.text()),incoming=Array.isArray(data)?data:data.products;if(!Array.isArray(incoming)||!incoming.length||incoming.length>100||incoming.some(p=>!p||typeof p.id!=='string'||typeof p.name!=='string')||new Set(incoming.map(p=>p.id)).size!==incoming.length)throw Error('Velg en gyldig fil med 1–100 unike produkter.');importDraft=incoming;el('importPreview').innerHTML='<ul>'+incoming.map(p=>'<li>'+escape(p.name)+' · '+(products.some(x=>x.id===p.id)?'oppdateres':'nytt produkt')+' · '+(p.rentalEnabled===false?'kun kjøp':'leie og kjøp')+' · '+escape(p.salePrice??'Pris avklares')+' kr</li>').join('')+'</ul>';el('saveImport').hidden=false;el('importStatus').textContent='Kontroller produktene ovenfor før du lagrer.';}catch(e){el('importStatus').textContent=e.message;}};
el('saveImport').onclick=async()=>{if(!importDraft||saving)return;if(dirty){el('importStatus').textContent='Lagre eller forkast produktendringene først.';return;}saving=true;el('saveImport').disabled=true;try{const ids=new Set(importDraft.map(p=>p.id)),next=[...products.map(p=>ids.has(p.id)?{...p,...importDraft.find(x=>x.id===p.id)}:p),...importDraft.filter(p=>!products.some(x=>x.id===p.id))];const data=await api('/api/admin/catalog',{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify({revision,products:next})});products=data.products;revision=data.revision;list();el('importStatus').textContent=importDraft.length+' produkter lagret på nettsiden.';importDraft=null;el('saveImport').hidden=true;el('catalogImport').value='';}catch(e){el('importStatus').textContent=e.message;}finally{saving=false;el('saveImport').disabled=false;}};

function loadPresentation(p){el('objectSortOrder').value=p.sortOrder||0;el('objectVariantOrder').value=p.variantOrder||0;el('objectVariantDisplay').value=p.variantDisplay||'auto';el('objectSwatchAutomatic').checked=!p.swatchColor;el('objectSwatchColor').value=p.swatchColor||'#b5ad99';el('objectSwatchColor').disabled=!p.swatchColor;el('objectPackageEditable').checked=p.packageEditable!==false;el('objectPackageCustomPricing').value=p.packageCustomPricing||'items';el('objectBuilderImage').value=p.builderImage||'';el('objectBuilderMirror').checked=!!p.builderMirror;for(let i=0;i<4;i++)el('builderCrop'+i).value=(p.builderCrop||[0,0,100,100])[i];}
function presentationFields(){return {sortOrder:Number(el('objectSortOrder').value),variantOrder:Number(el('objectVariantOrder').value),variantDisplay:el('objectVariantDisplay').value,swatchColor:el('objectSwatchAutomatic').checked?'':el('objectSwatchColor').value,packageEditable:el('objectPackageEditable').checked,packageCustomPricing:el('objectPackageCustomPricing').value,builderImage:el('objectBuilderImage').value.trim(),builderCrop:[0,1,2,3].map(i=>Number(el('builderCrop'+i).value)),builderMirror:el('objectBuilderMirror').checked};}
function renderBuilderPhoto(){const src=el('objectBuilderImage').value.trim(),crop=[0,1,2,3].map(i=>Number(el('builderCrop'+i).value));el('builderPhotoPreview').innerHTML=src?'<div style="position:relative;max-width:420px"><img src="'+escape(src)+'" alt="Bilde til sofabygger" style="display:block;width:100%;height:auto"><span style="position:absolute;border:3px solid #414b38;background:#414b381a;pointer-events:none;left:'+Math.max(0,crop[0])+'%;top:'+Math.max(0,crop[1])+'%;width:'+Math.max(0,crop[2]-crop[0])+'%;height:'+Math.max(0,crop[3]-crop[1])+'%"></span></div>':'<p class="hint">Bruker eksisterende produktbilde og sammenstilling.</p>';}
document.addEventListener('click',async event=>{const button=event.target.closest('[data-image-label]');if(!button)return;button.disabled=true;try{const current=await api('/api/admin/site-settings'),url=button.dataset.imageLabel,generated=!isKiPhoto(url),settings={...current.settings,imageLabels:[...current.settings.imageLabels.filter(x=>x.url!==url),{url,generated}]};const saved=await api('/api/admin/site-settings',{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify({revision:current.revision,settings})});configureSiteSettings(saved.settings);renderMedia();el('libraryStatus').textContent='Bildemerking lagret. Opplysningen vises under bildet på produktsiden.';}catch(error){showMediaError(error);button.disabled=false;}});
